import { type Ref, useImperativeHandle, useRef } from 'react';

import { useMergeRefs } from '../../../core/hooks/useMergeRefs.js';
import { type DataTableV2Ref } from '../public.api.js';

/*
 * This file manages the DataTableV2 config and imperative handle access features.
 */

export function useDataTableV2ConfigRef(props: {
  forwardedRef: Ref<DataTableV2Ref>;
}) {
  /*
   * Collect the refs and create an imperative handle in order to expose the
   * functions we need on the DataTableV2.
   */
  const containerRef = useRef<HTMLDivElement>(null);
  const rootRef = useMergeRefs<DataTableV2Ref | HTMLDivElement>([
    props.forwardedRef,
    containerRef,
  ]);

  useImperativeHandle(props.forwardedRef, () => ({
    element: containerRef.current,
    getConfig() {
      // TODO: Implement the config, if we still want to continue on this path.
      throw new Error('Not implemented');
    },
  }));

  return rootRef;
}
